/**
 * PaymentConfigForGet
 */
export interface apireference10json_PaymentConfigForGet {
  /** Default payment expiration days which will be used if the buyer did not provide the payment expiration date either in the payment or has not configured for the supplier.  The payment expiration days will be used to calculate the payment expiration date (payment process date + the payment expiration days) which is the last day by which the supplier should collect the payment. */
  expirationDays?: string;
  /** Denotes the ISO alpha currency code associated with the billing Currency of the card accounts belonging to the buyer. All ISO alpha currency codes will be supported. For example- USD for US Dollar. VPA system uses the billing currency as the payment currency for adjustable limit card accounts. */
  billingCurrency?: string;
  /** The list of currencies allowed for the buyer.  The buyer can process payments in any of these currencies.  Any payments made using any other currencies will be rejected.  All ISO alpha currency codes will be supported. For example- USD for US Dollar. */
  allowableCurrencies?: any[];
  /** Denotes if the security code needs to be enabled by default for all the new suppliers created. */
  defaultSecurityCode?: boolean;
  /** This option is used by the system to decide if all payments to the same supplier should be consolidated or sent separately in the payment advice notificaion. */
  paymentAdviceOption?: string;
  /** expirationBufferDays is the number of days after the payment expiration date by which the supplier needs to complete the collection of the payment (settlement of the card transaction should be completed). */
  expirationBufferDays?: string;
  /** Denotes if security code is needed for the supplier to collect the payment. */
  securityCodeRequired?: boolean;
}

/**
 * GetPaymentNotificationConfig
 */
export interface apireference10json_GetPaymentNotificationConfig {
  /** Denotes the date format which will be used for parsing date fields in the payment files in EDI or CVV tab format. */
  dateFormat?: string;
  /** Denotes the language (Locale like for e.g. en_US for US english ) which will be used in notifications sent to the buyer. */
  defaultBuyerLanguageCode?: string;
  /** Denotes if the remittance details file (containing the invoice details) will be attached to the payment advice notification while processig a payment. */
  attachRemittanceFileDetails?: boolean;
  /** Denotes the number of days before the payment expiration date when the system sends a reminder notification to the supplier. */
  supplierReminderNotificationDays?: string;
  /** Denotes if the system will send the payment reminder notification to the supplier (before the configured number of days (supplier reminder notification days) from the payment expiration date) to remind them to collect the payment. */
  supplierReminderNotificationEnabled?: boolean;
}

/**
 * Resend payment request payload
 */
export interface apireference10json_ResendPaymentRequest {
  /** Buyer ID is the buyer identifier as defined in Visa Payables Automation. Value format is 09. */
  buyerId: string;
  /** A '-' (hyphen) separated field which contains the region id, processor id and bank id */
  issuerId: string;
  /** Identifier used by the buyer to identify the vendor. This is the vendor id of the vendor whose payment is being modified. */
  vendorId: string;
  /** Client key for secure communication */
  clientKey?: string;
  /** Unique ID specific to this API call. */
  messageId: string;
  /** Extra notes for the email address */
  emailNotes?: string;
  /** An existing Visa card account. Values are 09. Note- If the account number is passed, it should correspond to the card account number used for the payment. */
  accountNumber?: string;
  /** Code Challenge for secure communication */
  codeChallenge?: string;
  /** The date by which a supplier must collect his payment. Format is YYYY-MM-DD */
  expirationDate?: string;
  /** This contains the email address for the supplier that will receive the payment instruction. It must be a valid email address. If the primary email address is provided, the payment advice will be sent to the new primary email address provided in the request. If it is not, the email address in the original request will be used. */
  primaryEmailAddress?: string;
  /** This complex element will contain up to five alternate email addresses. */
  alternateEmailAddresses?: any[];
  /** Unique ID used by that particular accounting software entity */
  accountingSoftwareEntityId: string;
  /** This field contains value as Y if supplier profile has to be updated and N if supplier profile should not be updated. By default, the system will not update the supplier profile with the new values sent in the request. */
  supplierProfileUpdateIndicator?: string;
}

